/* ============================================================
   Orbit 360 · Módulo CRM · Cliente 360  (NÚCLEO — base de oro)
   El "cerebro" del cliente: todo en un lugar, con desglose por
   póliza, cobro, renovación, comisión e historial.
   Master-detail. Deep-link: #/cliente360?c=cliID
   ============================================================ */
window.Orbit = window.Orbit || {};
Orbit.modules = Orbit.modules || {};
Orbit.modules.cliente360 = (function () {
  const U = Orbit.ui, q = Orbit.q, S = () => Orbit.store;
  // UAT2: render-only alias of existing canonical person/entity values.
  // Do not alter Firestore, identity, filter scope or policy ownership.
  function tipoClienteVisible(value) {
    const raw=String(value==null?'':value).trim();
    const key=raw.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()
      .replace(/[_-]+/g,' ').replace(/\s+/g,' ');
    if(['natural','persona','persona natural','persona fisica'].includes(key))return 'Persona';
    if(['juridica','juridico','persona juridica','empresa','sociedad'].includes(key))return 'Empresa';
    return raw;
  }
  const esRenovable = p => {
    if (!p || !['vigente','porrenovar'].includes(String(p.estado || '').trim().toLowerCase().replace(/\s+/g,''))) return false;
    const lifecycle = Orbit.renewalLifecycle && typeof Orbit.renewalLifecycle.evaluate === 'function'
      ? Orbit.renewalLifecycle.evaluate(p) : null;
    if (lifecycle) return !lifecycle.terminal && ![
      'LINEAGE_CONFLICTO', 'SUCESORA_DE_FUENTE_PENDIENTE_ENLACE',
      'RENOVADA_DECLARADA_SIN_SUCESORA_VERIFICADA'
    ].includes(lifecycle.reason);
    const outcome = String(p.renovacionEstado || '').trim().toLowerCase().replace(/[\s_-]+/g,'');
    return !p.renovadaPor && !['renovada','norenovada','cerrada','cancelada'].includes(outcome);
  };
  const esVigente = p => p && ['Vigente','Por renovar'].includes(q.policyDisplayStatus(p));
  const policyTotal = p => U.finiteNumber(p && p.primaTotal);

  // B4-003 UAT4: reconcile authorized policy scope against visible clients.
  function visiblePolicyGap(source, ids, role, country, hasFilters) {
    const r=String(role||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
    if(!['direccion','superadmin','admintenant'].includes(r)||country!=='TODOS'||hasFilters)return null;
    const total=Array.isArray(source)?source:[];
    const unmatched=total.filter(p=>p&&!ids.has(String(p.clienteId||'')));
    const active=unmatched.filter(esRenovable),currency={};
    active.forEach(p=>{
      const n=p.primaNeta!=null?p.primaNeta:p.prima;
      if(n==null||String(n).trim()==='')return;
      const val=Number(n);if(!Number.isFinite(val))return;
      const cur=String(p.moneda||p.divisa||'SIN_MONEDA');
      currency[cur]=(currency[cur]||0)+val;
    });
    return {total:total.length,unmatched:unmatched.length,active:active.length,currency};
  }

  const renovabilidad = p => {
    if (!p || !Object.prototype.hasOwnProperty.call(p, 'renovable') || p.renovable == null || String(p.renovable).trim() === '') return 'UNKNOWN';
    if (p.renovable === true || ['true', 'si', 'sí', 'renovable'].includes(String(p.renovable).trim().toLowerCase())) return 'YES';
    if (p.renovable === false || ['false', 'no', 'no renovable'].includes(String(p.renovable).trim().toLowerCase())) return 'NO';
    return 'UNKNOWN';
  };

  let host;
  let filtros = { q: '', pais: '', tipo: '', asesor: '', seg: '' };
  let tab = 'resumen';
  let shownCid = null; // cliente actualmente abierto (para resetear pestaña al cambiar)
  // In-memory drafts are private to the current tenant/actor/role and client.
  // A store repaint is not a successful save or an instruction to discard text.
  const historyDrafts = new Map();
  let historyView = null;
  let pendingRouteHydration = null;
  function waitForRoutedClient(cid) {
    const id=String(cid||'').trim(); if(!id) return false;
    if(pendingRouteHydration&&pendingRouteHydration.cid===id) return true;
    if(pendingRouteHydration&&pendingRouteHydration.off){try{pendingRouteHydration.off();}catch(_){}}
    const state={cid:id,tries:0,off:null,timer:null}; pendingRouteHydration=state;
    const finish=()=>{if(state.off){try{state.off();}catch(_){}state.off=null;}if(state.timer){clearInterval(state.timer);state.timer=null;}if(pendingRouteHydration===state)pendingRouteHydration=null;};
    const retry=()=>{
      state.tries+=1;
      const p=(Orbit.route&&Orbit.route.params)||{};
      if(String(p.c||'').trim()!==id){finish();return;}
      if(S().get('clientes',id)){finish();try{render(host);}catch(_){}return;}
      if(state.tries>=80)finish();
    };
    try{if(S()&&typeof S()._ensureCollections==='function')S()._ensureCollections(['clientes','polizas','recibosEsperados','carteraPrimas','cobros']);}catch(_){}
    try{if(S()&&typeof S().on==='function')state.off=S().on('*',()=>retry());}catch(_){}
    state.timer=setInterval(retry,250); retry(); return true;
  }
  const receiptReturnSummaryCache = new Map();
  const RECEIPT_RETURN_DEPS = ['clientes','polizas','cobros','recibosEsperados','carteraPrimas','comisiones','asesores'];
  function receiptReturnReady() {
    try { const store=S(),ps=store&&store._productStatus?store._productStatus():{},confirmed=[].concat(ps.serverConfirmedCollections||[]); return RECEIPT_RETURN_DEPS.every(name=>confirmed.includes(name)); }
    catch(_) { return true; }
  }
  function prepareReceiptReturn(cid) {
    const id=String(cid||'').trim(); if(!id||receiptReturnSummaryCache.has(id)) return false;
    const store=S();
    try { if(store&&typeof store._ensureCollections==='function') store._ensureCollections(RECEIPT_RETURN_DEPS); } catch(_) {}
    const run=()=>{try{if(!receiptReturnReady())return false;const r=q.clienteResumen(id);if(r&&r.cli)receiptReturnSummaryCache.set(id,r);return true;}catch(_){return false;}};
    if(run()) return true;
    if(store&&typeof store.on==='function'){let off=null;off=store.on('*',()=>{if(run()&&off){off();off=null;}});}
    return true;
  }
  function summaryForDetail(cid) {
    const id=String(cid||'').trim();
    if(tab==='recibos'&&receiptReturnSummaryCache.has(id)){const r=receiptReturnSummaryCache.get(id);receiptReturnSummaryCache.delete(id);return r;}
    return q.clienteResumen(cid);
  }
  try{document.addEventListener('orbit:store',e=>{const c=e&&e.detail&&e.detail.collection||'';if(['clientes','polizas','recibosEsperados','carteraPrimas','cobros','comisiones','*'].includes(c))receiptReturnSummaryCache.clear();});document.addEventListener('orbit:session',()=>receiptReturnSummaryCache.clear());}catch(_){};
  const LIST_PAGE_SIZE = 40;
  let listPage = 1;
  let listRenderSeq = 0;
  let listWaitingForReady = false;
  let listReadyTimer = null;
  let advisorListRefreshTimer = null;
  const perfNow = () => (typeof performance !== 'undefined' && performance.now ? performance.now() : Date.now());
  function dataReadiness(names) {
    const store = S();
    if (!store || store.__productReadOnlyP0 !== true || typeof store._productStatus !== 'function') return 'ready';
    const ps = store._productStatus() || {}, confirmed = [].concat(ps.serverConfirmedCollections || []), denied = [].concat(ps.deniedCollections || []), errors = ps.snapshotErrors || {};
    if (names.some(name => denied.includes(name) || !!errors[name])) return 'unavailable';
    return names.every(name => confirmed.includes(name)) ? 'ready' : 'pending';
  }
  function ensureDataCollections(names) { try { const store=S(); if(store&&typeof store._ensureCollections==='function') store._ensureCollections(names); } catch (_) {} }
  const DETAIL_DATA_DEPS = ['clientes','polizas','recibosEsperados','carteraPrimas','cobros','comisiones','asesores','gestiones'];
  function clientListDataReady() {
    const store = S();
    const projectionReady = !!(Orbit.clientProjection && typeof Orbit.clientProjection.withReadBatch === 'function');
    if (!projectionReady) return false;
    if (!store || store.__productReadOnlyP0 !== true || typeof store._productStatus !== 'function') return true;
    const ps = store._productStatus() || {};
    const confirmed = ps.serverConfirmedCollections || [];
    return ['clientes'].every(name => confirmed.includes(name));
  }
  function scheduleClientListReadyRender(delay) {
    if (!listWaitingForReady || listReadyTimer) return;
    listReadyTimer = setTimeout(() => {
      listReadyTimer = null;
      if (!listWaitingForReady || shownCid || !host || !clientListDataReady()) return;
      lista();
    }, Math.max(0, Number(delay) || 0));
  }
  function renderClientListLoading() {
    host.innerHTML = `<div class="page">${Orbit.kit.bannerFor('cliente360', '')}<div class="card pad" data-c360-authoritative-loading="1"><b>Cargando cartera de clientes…</b><div class="muted" style="margin-top:5px">Confirmando clientes y pólizas. Los indicadores financieros se completan en segundo plano sin bloquear la lista.</div></div></div>`;
  }
  function ensureClientNameCaseStyle() {
    if (document.getElementById('c360-client-name-case-style')) return;
    const style = document.createElement('style');
    style.id = 'c360-client-name-case-style';
    style.textContent = '.c360-client-name,#crm-kpi-v1198 [data-client] b{text-transform:uppercase;}';
    document.head.appendChild(style);
  }
  // visibilidad por rol (la comisión de empresa es interna/configurable)
  const ROLE = () => (Orbit.session && Orbit.session.rol && Orbit.session.rol()) || (Orbit.auth && Orbit.auth.user() && Orbit.auth.user().rol) || 'Dirección';
  const ROLE_NORM = () => String(ROLE()||'').trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'_');
  const advisorRole = () => ['asesor','asesora','asesor_sr','asesora_sr','asesor_jr','asesora_jr','comercial'].includes(ROLE_NORM());
  const verEmpresa = () => ['Dirección', 'Admin', 'Finanzas'].includes(ROLE());
  function sourceCurrencyTotals(rows, amountOf, currencyOf) {
    const totals = {};
    (rows || []).forEach(row => {
      const raw = amountOf(row);
      if (raw == null || String(raw).trim() === '') return;
      const n = U.finiteNumber(raw);
      if (n == null) return;
      const cur = String(currencyOf(row) || 'SIN_MONEDA').trim().toUpperCase() || 'SIN_MONEDA';
      totals[cur] = (totals[cur] || 0) + n;
    });
    return totals;
  }
  function currencyTotalsHtml(totals, short) {
    const pairs = Object.entries(totals || {}).sort(([a], [b]) => a.localeCompare(b));
    if (!pairs.length) return '<span class="muted">Sin importes confirmados</span>';
    return pairs.map(([cur, value]) => '<span data-c360-currency="' + U.esc(cur) + '" style="display:block">' +
      (cur === 'SIN_MONEDA' ? 'Moneda por validar · ' + Number(value).toLocaleString('es-GT') :
        (short ? U.moneyShort(value, cur) : U.money(value, cur)) + ' ' + U.esc(cur)) + '</span>').join('');
  }
  function summaryMoney(r, key, short) {
    const html = currencyTotalsHtml(r && r.porMoneda && r.porMoneda[key], short);
    const unknown = key === 'vencido' ? Number(r && r.carteraVencidaSinMonto || 0) : 0;
    return html + (unknown ? '<span class="badge warn" data-c360-overdue-unverified="' + unknown + '" style="display:block;margin-top:3px">' + unknown + ' obligación(es) con importe o moneda por validar</span>' : '');
  }
  // Estado de validación del cobro (coherente con Cobros): reportado ≠ aplicado
  function cobBadge(c) {
    let e, tone;
    if (c.estado === 'Pagado') { e = c.conciliado ? 'Conciliado' : 'Pagado (por conciliar)'; tone = 'ok'; }
    else if (c.validadoReporte && (c.estado === 'Pendiente' || c.estado === 'Vencido')) { e = 'Validada (por confirmar)'; tone = 'ok'; }
    else if (c.requiereValidacion) { e = 'Requiere validación'; tone = 'warn'; }
    else if (c.estado === 'Bloqueado') { e = 'Bloqueado'; tone = 'danger'; }
    else if (c.reportado && (c.estado === 'Pendiente' || c.estado === 'Vencido')) { e = c.enRevision ? 'En revisión' : 'Reportado por cliente'; tone = 'info'; }
    else if (c.estado === 'Vencido') { e = 'Vencido'; tone = 'danger'; }
    else { e = c.estado || 'Pendiente'; tone = 'warn'; }
    return '<span class="badge ' + tone + '">' + e + '</span>';
  }

  const TABS = ['resumen', 'polizas', 'vehiculos', 'cobros', 'recibos', 'gestiones', 'renovaciones', 'siniestros', 'documentos', 'comisiones', 'correos', 'historial'];
  window.addEventListener('orbit:store:emit', event => {
    if (!listWaitingForReady) return;
    const collection = event && event.detail && event.detail.collection;
    if (!collection || ['*','clientes','polizas','carteraPrimas','cobros','asesores'].includes(collection)) scheduleClientListReadyRender(0);
  });
  // C360's client scope may forbid reading Equipo. The authorized policy
  // projection already carries verified adviser labels; repaint when it arrives
  // rather than leaving an entire Operativo table with permanent dashes.
  window.addEventListener('orbit:store:emit', event => {
    const collection = event && event.detail && event.detail.collection;
    if (!['polizas','asesores'].includes(collection) || listWaitingForReady || shownCid ||
        !host || !host.isConnected || !host.querySelector ||
        !host.querySelector('[data-c360-list-ready]') || advisorListRefreshTimer) return;
    advisorListRefreshTimer = setTimeout(() => {
      advisorListRefreshTimer = null;
      if (!shownCid && host && host.isConnected && /^#\/cliente360(?:[?\/]|$)/.test(location.hash || '')) lista();
    }, 120);
  });
  // Refresh the visible client panel when canonical Ops records arrive or change.
  let managementRefreshTimer=null;
  window.addEventListener('orbit:store:emit',event=>{
    const collection=event&&event.detail&&event.detail.collection;
    if(!['gestiones','actividades','negocios'].includes(collection)||!shownCid||!host||!host.isConnected||managementRefreshTimer)return;
    if(!['resumen','gestiones','historial'].includes(tab))return;
    managementRefreshTimer=setTimeout(()=>{
      managementRefreshTimer=null;
      if(shownCid&&host&&host.isConnected&&document.getElementById('c360-body')){
        try{renderTab(shownCid,summaryForDetail(shownCid));}catch(_){}
      }
    },120);
  });
  window.addEventListener('orbit:lab:canonical-view-hydrated', () => scheduleClientListReadyRender(0));

  // ---------- entry ----------
  function render(h) {
    rememberHistoryDraft();
    host = h;
    ensureClientNameCaseStyle();
    const p = (Orbit.route && Orbit.route.params) || {};
    const cid = p.c || null;
    const requested = cid && S().get('clientes', cid);
    if (requested && !clientInCurrentCountry(requested)) {
      shownCid = null;
      tab = 'resumen';
      host.innerHTML = '<div class="page"><div class="card pad">El expediente está fuera del país seleccionado. <a href="#/cliente360">Volver a Clientes 360</a></div></div>';
      return;
    }
    if (cid) ensureDataCollections(DETAIL_DATA_DEPS);
    if (requested) {
      if (requested && String(requested.mergedIntoClientId || '').trim()) {
        const canonicalId = String(requested.mergedIntoClientId || '').trim();
        if (S().get('clientes', canonicalId)) {
          location.hash = '#/cliente360?c=' + encodeURIComponent(canonicalId) + (p.t ? '&t=' + encodeURIComponent(p.t) : '');
          return;
        }
      }
      // al abrir un cliente distinto, o llegar con pestaña explícita, fijar la pestaña
      if (p.t && TABS.includes(p.t)) tab = p.t;
      else if (cid !== shownCid) tab = 'resumen';
      shownCid = cid;
      detalle(cid);
    } else if (cid) {
      shownCid = null;
      host.innerHTML = '<div class="page"><div class="card pad" data-c360-route-loading="1"><b>Cargando cliente…</b><div class="muted" style="margin-top:5px">Estamos preparando el expediente solicitado.</div></div></div>';
      waitForRoutedClient(cid);
    } else {
      shownCid = null;
      lista();
    }
  }

  /* =========================================================
     LISTA (cartera de clientes)
     ========================================================= */
  function clientInCurrentCountry(client) {
    const selected = String(Orbit.pais || 'TODOS').trim().toUpperCase();
    return selected === 'TODOS' || String(client && client.pais || '').trim().toUpperCase() === selected;
  }
  function lista() {
    const f = filtros;
    ensureDataCollections(['clientes','polizas','asesores','carteraPrimas']);
    if (!clientListDataReady()) {
      listWaitingForReady = true;
      renderClientListLoading();
      scheduleClientListReadyRender(250);
      return;
    }
    listWaitingForReady = false;
    const renderStartedAt = perfNow();
    const summaryStartedAt = perfNow();
    // R14: server-confirmed product store is the authoritative base universe.
    // Projection helpers may enrich summaries but may not replace it with an empty/stale snapshot.
    const clientesRaw = S().all('clientes');
    const clientesAll = (clientesRaw || []).filter(c => !(c && (c.fusionado === true || String(c.mergedIntoClientId || '').trim())));
    const globalCountry = String(Orbit.pais || 'TODOS').trim().toUpperCase();
    const clientes = clientesAll.filter(clientInCurrentCountry);
    const policyReadiness = dataReadiness(['polizas']);
    if (policyReadiness === 'pending') ensureDataCollections(['polizas']);
    const policiesRaw = policyReadiness === 'ready' ? S().all('polizas') : [];
    // Cliente 360 is client-centric: once the visible client universe is scoped,
    // include every policy linked to those clients. Policy-country discrepancies
    // remain visible for validation instead of silently dropping client history.
    const policiesForList = policiesRaw;
    const asesores = S().all('asesores');
    // Only names attached to already-authorized policy documents are projected
    // for Operativo; never expand the sensitive Equipo/asesores collection.
    const policyAdvisorLabels = policiesForList.filter(p => p && p.asesorId &&
      typeof p.asesorNombreVerificado === 'string' && p.asesorNombreVerificado.trim())
      .map(p => ({ id: p.asesorId, nombre: p.asesorNombreVerificado }));
    const advisorById = new Map([...policyAdvisorLabels, ...asesores.filter(a => a && a.id != null)]
      .map(a => [a.id, a]));
    const advisorOptions = [...advisorById.values()].sort((a, b) => String(a.nombre || '').localeCompare(String(b.nombre || '')));
    const policyByClient = new Map();
    const addRelated = (map, clientId, row) => {
      if (clientId == null) return;
      let bucket = map.get(clientId);
      if (!bucket) { bucket = []; map.set(clientId, bucket); }
      bucket.push(row);
    };
    policiesForList.forEach(p => { if (p) addRelated(policyByClient, p.clienteId, p); });
    const portfolioReadiness = dataReadiness(['carteraPrimas']);
    if (portfolioReadiness === 'pending') ensureDataCollections(['carteraPrimas']);
    const canonicalSummaryIndex = policyReadiness === 'ready' && portfolioReadiness === 'ready' && q.clientesResumenIndex ? q.clientesResumenIndex() : null;
    const summaryCacheMs = perfNow() - summaryStartedAt;
    const rows = clientes.filter(c =>
      (!f.q || (c.nombre + ' ' + c.email + ' ' + c.identificacion).toLowerCase().includes(f.q.toLowerCase())) &&
      (!f.pais || c.pais === f.pais) &&
      (!f.tipo || tipoClienteVisible(c.tipo) === f.tipo) &&
      (!f.asesor || c.asesorId === f.asesor) &&
      (!f.seg || c.segmento === f.seg)
    );
    // QA fixtures remain browsable as audit records, but do not enter commercial client KPIs.
    const isQaRecord = row => typeof q.isSyntheticQaRecord === 'function' && q.isSyntheticQaRecord(row);
    const commercialClientRows = rows.filter(c => !isQaRecord(c));
    const qaAuditClientCount = rows.length - commercialClientRows.length;
    const kpiClientIds = new Set(commercialClientRows.map(c => String(c && c.id || '')).filter(Boolean));
    const policiesForKpi = policiesForList.filter(p => p && !isQaRecord(p) &&
      !isQaRecord(S().get('clientes', p.clienteId)) && kpiClientIds.has(String(p.clienteId || '')));
    const pageCount = Math.max(1, Math.ceil(rows.length / LIST_PAGE_SIZE));
    if (listPage > pageCount) listPage = pageCount;
    if (listPage < 1) listPage = 1;
    const pageStart = (listPage - 1) * LIST_PAGE_SIZE;
    const visibleRows = rows.slice(pageStart, pageStart + LIST_PAGE_SIZE);
    const resumenDe = c => {
      if (policyReadiness !== 'ready') return { moneda: c ? c.moneda : 'GTQ', nPolizas: null, nVigentes: null, primaAnual: null, pendiente: null, vencido: null, salud: null, readiness: 'pending', policyReadiness };
      const pol = policyByClient.get(c.id) || [];
      const vigentes = pol.filter(esRenovable);
      const primaAnual = vigentes.reduce((s, p) => s + (policyTotal(p) || 0), 0);
      const canonical = canonicalSummaryIndex && canonicalSummaryIndex.get(c.id);
      return canonical || { moneda: c ? c.moneda : 'GTQ', nPolizas: pol.length, nVigentes: vigentes.length, primaAnual,
        porMoneda: { primaAnual: sourceCurrencyTotals(vigentes, p => policyTotal(p), p => p.moneda || p.divisa) },
        pendiente: null, vencido: null, salud: null, readiness: portfolioReadiness, policyReadiness };
    };
    const summaryAggregateStartedAt = perfNow();
    const clientById = new Map(clientes.filter(c => c && c.id != null).map(c => [c.id, c]));
    const primaNetaVigentePorMoneda = {};
    policiesForKpi.forEach(p => {
      if (!esVigente(p)) return;
      const cli = clientById.get(p.clienteId);
      if (!cli) return;
      const neta = U.finiteNumber(p.primaNeta != null ? p.primaNeta : p.prima);
      if (neta == null) return;
      const moneda = String(p.moneda || p.divisa || cli.moneda || 'SIN_MONEDA').trim() || 'SIN_MONEDA';
      primaNetaVigentePorMoneda[moneda] = (primaNetaVigentePorMoneda[moneda] || 0) + neta;
    });
    const primaNetaVigenteKeys = Object.keys(primaNetaVigentePorMoneda);
    const primaNetaVigenteHtml = policyReadiness !== 'ready'
      ? '<span class="muted" data-c360-policy-readiness="' + U.esc(policyReadiness) + '">Actualizando datos</span>'
      : (primaNetaVigenteKeys.sort((a, b) => {
          const rank = x => x === 'GTQ' ? 0 : x === 'COP' ? 1 : 2;
          return rank(a) - rank(b) || a.localeCompare(b);
        }).map(moneda => '<span style="display:block;font-size:' + (primaNetaVigenteKeys.length > 1 ? '14px' : '22px') + '">' + U.esc(moneda) + ' ' + Number(primaNetaVigentePorMoneda[moneda] || 0).toLocaleString('es-GT', { maximumFractionDigits: 0 }) + '</span>').join('') || '<span class="muted">Sin valores</span>');
    const activePolicyCount = policyReadiness === 'ready' ? policiesForKpi.filter(esVigente).length : null;
    const totalPolicyCount = policyReadiness === 'ready' ? policiesForKpi.length : null;
    const renewals45Policies = policyReadiness === 'ready' ? policiesForKpi.filter(p => { const d = U.daysFromNow(p.vigenciaFin); return esRenovable(p) && d != null && d >= 0 && d <= 45; }) : [];
    const renewals45Count = policyReadiness === 'ready' ? renewals45Policies.length : null;
    const selectedRole=Orbit.session&&typeof Orbit.session.rol==='function'?Orbit.session.rol():'';
    const hasFilters=Boolean(f.q||f.pais||f.tipo||f.asesor||f.seg);
    const commercialPoliciesForGap=policiesForList.filter(p=>p && !isQaRecord(p) && !isQaRecord(S().get('clientes',p.clienteId)));
    const policyGap=policyReadiness==='ready'?visiblePolicyGap(commercialPoliciesForGap,kpiClientIds,selectedRole,globalCountry,hasFilters):null;
    const policyGapNote=policyGap&&policyGap.unmatched>0?policyGap.unmatched+' pólizas sin cliente visible':'';
    const summaryAggregateMs = perfNow() - summaryAggregateStartedAt;

    const rowsBuildStartedAt = perfNow();
    const rowsHtml = visibleRows.map(c => {
            const r = resumenDe(c);
            const isQaAudit = isQaRecord(c);
            const ase = advisorById.get(c.asesorId) || null;
            const financialReady = r.salud != null && r.vencido != null;
            const cartera = !financialReady
