    const more = document.getElementById('ftab-more');
    const prev = document.getElementById('ftab-prev');
    if (!wrap || !strip || !more || !prev) return;
    const upd = () => {
      const overflow = strip.scrollWidth - strip.clientWidth;
      const atEnd = strip.scrollLeft >= overflow - 2;
      wrap.classList.toggle('has-more', overflow > 4 && !atEnd);
      wrap.classList.toggle('has-prev', strip.scrollLeft > 2);
    };
    strip.addEventListener('scroll', upd);
    window.addEventListener('resize', upd);
    more.addEventListener('click', () => strip.scrollBy({ left: strip.clientWidth * 0.7, behavior: 'smooth' }));
    prev.addEventListener('click', () => strip.scrollBy({ left: -strip.clientWidth * 0.7, behavior: 'smooth' }));
    // llevar la pestaña activa a la vista
    const act = strip.querySelector('.ftab.active');
    if (act) { const off = act.offsetLeft - 12; if (off > strip.scrollLeft + strip.clientWidth - act.offsetWidth || off < strip.scrollLeft) strip.scrollLeft = off; }
    setTimeout(upd, 30);
  }

  function kpiCell(label, val, tone, icon, readiness) {
    const col = tone === 'ok' ? 'var(--ok)' : tone === 'danger' ? 'var(--danger)' : 'var(--ink)';
    const ac = tone === 'ok' ? 'var(--ok)' : tone === 'danger' ? 'var(--danger)' : 'var(--red)';
    return `<div class="fh-kpi" data-c360-kpi="${U.esc(label)}" data-readiness="${readiness || 'ready'}"><span class="fh-kpi-ac" style="background:${ac}"></span>
      <div class="fh-kpi-lab">${icon ? `<span>${icon}</span>` : ''}${label}</div>
      <div class="fh-kpi-val" style="color:${col}">${val}</div></div>`;
  }
  function kpiMetricCell(label, val, tone, icon, readiness) {
    if (readiness === 'ready') return kpiCell(label, val, tone, icon, 'ready');
    const state = readiness === 'unavailable' ? 'No disponible' : 'Actualizando datos';
    return `<div class="fh-kpi" data-c360-kpi="${U.esc(label)}" data-readiness="${readiness}"><span class="fh-kpi-ac" style="background:var(--line)"></span><div class="fh-kpi-lab">${icon ? `<span>${icon}</span>` : ''}${label}</div><div class="fh-kpi-val muted" style="font-size:13px">${state}</div></div>`;
  }

  function renderTab(cid, r) {
    rememberHistoryDraft();
    historyView = null;
    const body = document.getElementById('c360-body');
    const coreFinancialReadiness = dataReadiness(['clientes','polizas','carteraPrimas','cobros']);
    if ((tab === 'resumen' || tab === 'cobros') && coreFinancialReadiness !== 'ready') {
      body.innerHTML = `<div class="card pad" data-c360-financial-pending="1" data-readiness="${coreFinancialReadiness}"><b>${coreFinancialReadiness === 'unavailable' ? 'Información no disponible para este acceso' : 'Actualizando datos…'}</b><div class="muted" style="margin-top:5px">Estamos confirmando pólizas, cartera y pagos antes de mostrar un resultado definitivo.</div></div>`;
      return;
    }
    if (tab === 'resumen') body.innerHTML = tabResumen(cid, r);
    else if (tab === 'polizas') body.innerHTML = tabPolizas(cid, r);
    else if (tab === 'vehiculos') body.innerHTML = tabVehiculos(cid, r);
    else if (tab === 'recibos') {
      const ps = S() && typeof S()._productStatus === 'function' ? S()._productStatus() : {};
      const confirmed = ps.serverConfirmedCollections || [];
      const receiptState = dataReadiness(['recibosEsperados','carteraPrimas']);
      if (receiptState !== 'ready') {
        ensureDataCollections(['recibosEsperados','carteraPrimas']);
        body.setAttribute('data-c360-receipts-loading',receiptState);
        body.innerHTML = receiptState === 'unavailable'
          ? '<div class="card pad" data-c360-receipts-unavailable="1" data-readiness="unavailable"><b>No fue posible confirmar recibos y cartera</b><div class="muted" style="margin-top:5px">La lectura autorizada devolvió un error o una restricción. No se muestran cuotas ni saldos provisionales.</div></div>'
          : '<div class="card pad" data-c360-receipts-pending="1" data-readiness="pending"><b>Cargando recibos…</b><div class="muted" style="margin-top:5px">Estamos validando el calendario y la cartera en la fuente canónica.</div></div>';
      } else {
        body.removeAttribute('data-c360-receipts-loading');
        const projection = Orbit.receiptsPortfolioProjection;
        if (projection && typeof projection.renderReceipts === 'function') projection.renderReceipts(cid);
        else { body.innerHTML = tabRecibos(cid, r); wireRecibos(cid); }
      }
    }
    else if (tab === 'cobros') { body.innerHTML = tabCobros(cid, r); wireCobros(cid, r); }
    else if (tab === 'gestiones') { body.innerHTML = tabGestiones(cid); wireGestiones(); }
    else if (tab === 'renovaciones') body.innerHTML = tabRenov(cid, r);
    else if (tab === 'documentos') { body.innerHTML = tabDocumentos(cid, r); wireDocumentos(cid); }
    else if (tab === 'comisiones') body.innerHTML = tabComis(cid, r);
    else if (tab === 'correos') { body.innerHTML = tabCorreos(cid, r); }
    else if (tab === 'siniestros') { body.innerHTML = tabSiniestros(cid, r); }
    else if (tab === 'historial') { body.innerHTML = tabHistorial(cid, r); wireHistorial(cid); }
    for (const button of body.querySelectorAll('[data-c360-negocio]')) {
      button.onclick = () => Orbit.ciclo.openNegocio(button.dataset.c360Negocio);
    }
  }

  /* A single server-owned Ops management appears in Cliente360 and Historial
     without duplicating its business record or inventing an activity write. */
  function gestionesCliente(cid) {
    if(dataReadiness(['gestiones'])!=='ready'||!Orbit.ciclo||typeof Orbit.ciclo.gestiones!=='function')return[];
    return Orbit.ciclo.gestiones({surface:'ops',includeBoardHidden:true})
      .filter(g=>g&&String(g.clienteId||'')===String(cid||''));
  }
  function commercialHistorySurfaces() {
    return ['leads','ops'].filter(surface => Orbit.access?.can?.(surface,'view') === true);
  }

  function commercialHistory(cid, saved) {
    if (!cid || dataReadiness(['negocios']) !== 'ready' || !Orbit.ciclo?.negocios) return [];
    const deals = new Map();
    for (const surface of commercialHistorySurfaces()) {
      for (const deal of Orbit.ciclo.negocios({surface, incArchivado:true})) {
        if (deal.id && deal.clienteId === cid) deals.set(deal.id, deal);
      }
    }
    const events = [];
    for (const deal of deals.values()) {
      const seen = new Set(saved.filter(a => a.negocioId === deal.id && a.eventId).map(a => a.eventId));
      const comments = Array.isArray(deal.comentarios) ? deal.comentarios : [];
      const history = Array.isArray(deal.bitacora) ? deal.bitacora : [];
      const add = (entry, title, detail) => {
        if (!entry || (entry.eventId && seen.has(entry.eventId))) return;
        if (entry.eventId) seen.add(entry.eventId);
        events.push({icon:'🎯', tipo:'negocio', negocioId:deal.id, eventId:entry.eventId,
          fecha:entry.ts || '', actor:entry.actorName || entry.user || '',
          titulo:title || 'Oportunidad', detalle:detail || ''});
      };
      for (const c of comments) {
        if (c) add(c, c.tipo || 'Comentario', c.texto);
      }
      for (const h of history) {
        if (h) add(h, h.campo || 'Oportunidad', h.a);
      }
      if (!history.length && !comments.length && deal.creado) {
        add({ts:deal.creado}, 'Oportunidad creada', deal.etapa);
      }
    }
    return events;
  }

  function commercialEventLink(a) {
    if (!a.negocioId) return '';
    return '<button type="button" class="btn ghost sm" data-c360-negocio="'+U.esc(a.negocioId)+'">Abrir oportunidad</button>';
  }

  function commercialHistoryNotice() {
    if (!commercialHistorySurfaces().length) return '';
    const status = dataReadiness(['negocios']);
    if (status === 'ready') return '';
    return '<p class="muted" role="status">'+(status === 'unavailable'
      ? 'No fue posible consultar el historial de oportunidades.'
      : 'Consultando el historial de oportunidades…')+'</p>';
  }

  function actividadesCliente(cid) {
    const saved=[].concat(q.actividadesDe(cid)||[]).filter(a => ![...historyDrafts.values()]
      .some(d => d.attempt && d.attempt.activity.id === a.id));
    const seen=new Set(saved.map(a=>String(a&&a.gestionId||'')).filter(Boolean));
    const managements=gestionesCliente(cid).filter(g=>!seen.has(String(g.id||'')))
      .map(g=>({
        icon:'🗂',tipo:'gestion',gestionId:g.id,asesorId:g.asesorId,
        fecha:String(g.creado||g.actualizado||'').slice(0,10),
        titulo:'Gestión · '+String(g.titulo||g.tipo||'Seguimiento'),
        detalle:String(g.estado||'Pendiente')+' · '+String(g.proximaAccion||'Sin próxima acción')
      }));
    return saved.concat(managements, commercialHistory(cid, saved))
      .sort((a,b)=>String(b.fecha||'').localeCompare(String(a.fecha||'')));
  }
