      const paymentDate = x.fechaPagoReportada || x.fechaPago || '';
      const method = x.metodoPago || x.metodo || x.formaPago || '';
      return `<tr data-advisor-reported-payment="1">
        <td><span class="mono" style="font-size:12px">${p ? p.numero : (x.polizaNumero || '—')}</span></td>
        <td>${U.esc(x.serie || x.cuota || x.numeroReciboFuente || '—')}</td>
        <td class="num">${amount == null ? '<span class="muted">—</span>' : U.money(amount, x.moneda || (p && p.moneda) || r.moneda)}</td>
        <td style="font-size:12.5px">${U.fmtDate(x.fechaLimite || x.vence || x.fechaVencimiento)}</td>
        <td style="font-size:12.5px">${paymentDate ? U.fmtDate(paymentDate) : '<span class="muted">—</span>'}</td>
        <td style="font-size:12.5px">${method ? U.esc(method) : '<span class="muted">—</span>'}</td>
        <td><span class="badge info">Pago reportado por asesor</span></td>
        <td><span class="badge warn">Pendiente de validación operativa</span></td>
        <td>${advisorRole() ? '<span class="badge info">Enviado a Ops</span>' : `<button class="btn primary sm" data-c360-aplicar-reporte="${U.esc(x.id)}">Validar y aplicar</button>`}</td>
      </tr>`;
    }).join('');
    const reportedRows = reported.map(x => {
      const p = S().get('polizas', x.polizaId);
      const amount = U.finiteNumber(x.primaTotal != null ? x.primaTotal : (x.montoTotal != null ? x.montoTotal : x.monto));
      const paymentDate = x.fechaPagoReportada || x.fechaPago || '';
      const method = x.metodoPago || x.metodo || x.formaPago || '';
      return `<tr data-reported-payment-evidence="1">
        <td><span class="mono" style="font-size:12px">${p ? p.numero : (x.polizaNumero || '—')}</span></td>
        <td>${U.esc(x.serie || x.cuota || x.numeroReciboFuente || '—')}</td>
        <td class="num">${amount == null ? '<span class="muted">—</span>' : U.money(amount, x.moneda || (p && p.moneda) || r.moneda)}</td>
        <td style="font-size:12.5px">${U.fmtDate(x.fechaLimite || x.vence || x.fechaVencimiento)}</td>
        <td style="font-size:12.5px">${paymentDate ? U.fmtDate(paymentDate) : '<span class="muted">—</span>'}</td>
        <td style="font-size:12.5px">${method ? U.esc(method) : '<span class="muted">—</span>'}</td>
        <td><span class="badge info">Pago reportado · pendiente de aplicación automática</span></td>
        <td><span class="badge warn">Pendiente</span></td>
        <td><span class="muted">Aplicar desde Recibos y pagos</span></td>
      </tr>`;
    }).join('');
    const unknownRows = unknownEvidence.map(x => { const p=S().get('polizas',x.polizaId); return `<tr data-payment-origin-review="1"><td><span class="mono" style="font-size:12px">${p?p.numero:'—'}</span></td><td>${U.esc(x.serie||x.cuota||'—')}</td><td colspan="5"><span class="badge warn">Origen de pago por confirmar</span></td><td><span class="badge warn">Revisión</span></td><td></td></tr>`; }).join('');
    const visibleRows = confirmedRows + crmDirectRows + paidReceiptRows + advisorReportedRows + reportedRows + unknownRows;
    const noteParts = [];
    if (crmDirect.length) noteParts.push(`<b>${crmDirect.length}</b> pago(s) registrados en SIGA: conservan conciliación automática por lote y también conciliación individual.`);
    if (paidReceipt.length) noteParts.push(`<b>${paidReceipt.length}</b> pago(s) aplicado(s) proyectados desde recibos mientras no exista un cobro visible; no se duplican cuando aparece el cobro canónico.`);
    if (advisorReported.length) noteParts.push(`<b>${advisorReported.length}</b> pago(s) reportado(s) por asesor pendientes de validación operativa en Ops.`);
    if (reported.length) noteParts.push(`<b>${reported.length}</b> pago(s) realmente reportados desde portal pendientes de aplicación automática.`);
    if (unknownEvidence.length) noteParts.push(`<b>${unknownEvidence.length}</b> evidencia(s) con origen por confirmar.`);
    const note = noteParts.join(' ') || 'No hay pagos pendientes de conciliación para el filtro actual.';
    return `<div class="card" data-rp-native-cobros-note="1" style="padding:12px 14px;margin-bottom:12px"><b>Cobros y evidencia de pago</b><div class="muted" style="font-size:12.5px;margin-top:3px">${note} Los cobros confirmados se muestran en la misma tabla y su conciliación se mantiene separada.</div></div>
    <div style="display:flex;align-items:center;gap:10px;margin-bottom:12px"><label style="font-size:12.5px;font-weight:600;color:var(--ink-2)">Filtrar por póliza:</label><select id="cob-pol-fil" class="o-sel" style="max-width:360px;font-size:12.5px">${polOptions}</select></div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:14px">
      ${miniStat('Cobrado confirmado', summaryMoney(r,'cobrado'), 'ok')}
      ${miniStat('Cartera por vencer', summaryMoney(r,'pendiente'), 'warn')}
      ${miniStat('Cartera exigible', summaryMoney(r,'vencido'), r.carteraVencidaCount > 0 ? 'danger' : 'ok')}
    </div>
    <div class="card" style="overflow:hidden"><div style="overflow-x:auto"><table class="tbl">
      <thead><tr><th>Póliza</th><th>Cuota</th><th class="num">Monto</th><th>Vence</th><th>Pago</th><th>Método</th><th>Estado</th><th>Conciliación</th><th>Acción</th></tr></thead>
      <tbody>${visibleRows || '<tr><td colspan="9" class="muted" style="text-align:center;padding:28px">Sin cobros ni evidencia de pago para el filtro actual.</td></tr>'}</tbody>
    </table></div>
    <div style="padding:11px 14px;border-top:1px solid var(--line);font-size:12.5px;color:var(--ink-3)">Pago reportado ≠ cobro confirmado. Cobro confirmado ≠ necesariamente conciliado. La conciliación no cambia la fecha real del pago.</div></div>`;
  }

  function wireCobros(cid, r) {
    const body = document.getElementById('c360-body');
    if (!body) return;
    body.querySelectorAll('[data-c360-conciliar-receipt]').forEach(b => {
      if (b.dataset.c360Wired === '1') return;
      b.dataset.c360Wired = '1';
      b.addEventListener('click', e => {
        e.stopPropagation();
        if (Orbit.modules && Orbit.modules.cobros && typeof Orbit.modules.cobros.conciliarFactura === 'function') Orbit.modules.cobros.conciliarFactura(b.dataset.c360ConciliarReceipt);
        else U.toast('Conciliación canónica no disponible.');
      });
    });
    body.querySelectorAll('[data-c360-aplicar-reporte]').forEach(b => {
      if (b.dataset.c360Wired === '1') return;
      b.dataset.c360Wired = '1';
      b.addEventListener('click', e => {
        e.stopPropagation();
        if (Orbit.modules && Orbit.modules.cobros && typeof Orbit.modules.cobros.aplicarPago === 'function') Orbit.modules.cobros.aplicarPago(b.dataset.c360AplicarReporte);
        else U.toast('Aplicación canónica no disponible.');
      });
    });
    body.querySelectorAll('[data-c360-conciliar]').forEach(b => {
      if (b.dataset.c360Wired === '1') return;
      b.dataset.c360Wired = '1';
      b.addEventListener('click', e => {
        e.stopPropagation();
        if (Orbit.modules && Orbit.modules.cobros && typeof Orbit.modules.cobros.conciliarFactura === 'function') Orbit.modules.cobros.conciliarFactura(b.dataset.c360Conciliar);
        else U.toast('Conciliación canónica no disponible.');
      });
    });
    const pf = body.querySelector('#cob-pol-fil');
    if (pf) pf.addEventListener('change', () => {
      window._cobFilPol = window._cobFilPol || {};
      window._cobFilPol[cid] = pf.value;
      body.innerHTML = tabCobros(cid, r);
      wireCobros(cid, r);
    });
  }

  function miniStat(label, val, tone) {
    const col = tone === 'ok' ? 'var(--ok)' : tone === 'warn' ? 'var(--warn)' : tone === 'danger' ? 'var(--danger)' : 'var(--ink)';
    return `<div class="card" style="padding:13px 15px"><div style="font-size:11.5px;color:var(--ink-3);text-transform:uppercase;letter-spacing:.05em;font-weight:600">${label}</div>
      <div style="font-family:var(--f-display);font-weight:800;font-size:20px;margin-top:5px;color:${col}">${val}</div></div>`;
  }

  /* ---- Renovaciones ---- */
  function tabRenov(cid, r) {
    const items = r.pol.filter(esRenovable).slice().sort((a, b) => String(a.vigenciaFin||'').localeCompare(String(b.vigenciaFin||'')));
    return `<div class="card pad">
      <div class="c360-renewals-head">
        <b style="font-family:var(--f-display);font-size:15px">Línea de renovaciones</b>
        <button class="btn ghost sm" onclick="Orbit.ciclo.solicitarGestion('${cid}')">🗂 Solicitar gestión</button>
      </div>
      <div style="margin-top:16px;display:grid;gap:12px">
      ${items.map(p => {
        const d = U.daysFromNow(p.vigenciaFin);
        const estado = q.policyDisplayStatus(p) === 'Vencida' ? 'Vencida' : d != null && d <= 45 ? 'Por renovar' : q.policyDisplayStatus(p);
        const tone = estado === 'Vencida' ? 'danger' : estado === 'Por renovar' ? 'warn' : 'ok';
