          </div>
        </div>`;
      }).join('') || '<span class="muted">Sin pólizas para renovar.</span>'}
      </div>
    </div>`;
  }

  /* ---- Vehículos (detalle por póliza de auto) ---- */
  function vehicleShown(v) {
    const t=v==null?'':String(v).trim();
    return (!t||/^(undefined|null|\[object Object\])$/i.test(t))?'—':t;
  }
  function vehiclePolicyCompare(a,b) {
    const pa=S().get('polizas',a&&a.polizaId)||{},pb=S().get('polizas',b&&b.polizaId)||{};
    const rank=policyBusinessRank(pa)-policyBusinessRank(pb);
    if(rank) return rank;
    const date=policyBusinessDate(pb).localeCompare(policyBusinessDate(pa));
    if(date) return date;
    return String(a&&a.id||'').localeCompare(String(b&&b.id||''));
  }
  function canonicalVehicle(v) {
    if(!v||typeof v!=='object') return v;
    try {
      const n=Orbit.policyReceipts&&typeof Orbit.policyReceipts.normalizeVehicle==='function' ? Orbit.policyReceipts.normalizeVehicle(v) : null;
      return n?Object.assign({},v,n,{id:v.id,polizaId:v.polizaId,clienteId:v.clienteId,versionOfVehicleId:v.versionOfVehicleId||n.versionOfVehicleId||''}):Object.assign({},v);
    } catch(e) { return Object.assign({},v); }
  }
  function vehicleLineageRoot(v,byId) {
    let root=String(v&&v.id||''),parent=String(v&&v.versionOfVehicleId||''),seen=new Set();
    while(parent&&!seen.has(parent)){seen.add(parent);root=parent;const p=byId.get(parent);parent=String(p&&p.versionOfVehicleId||'');}
    return root;
  }
  function vehiclePlateKey(v) {
    return String(v&&v.placa||'').trim().toUpperCase().replace(/[^A-Z0-9]/g,'');
  }
  function tabVehiculos(cid, r) {
    const rawVs = q.vehiculosDe(cid);
    const vs = rawVs.map(canonicalVehicle);
    if (!vs.length) return `<div class="card pad"><span class="muted">Este cliente no tiene vehículos asegurados.</span></div>`;
    const groups = new Map(), ambiguous=[];
    const byId=new Map(vs.filter(v=>v&&v.id).map(v=>[String(v.id),v]));
    const referenced=new Set(vs.map(v=>String(v&&v.versionOfVehicleId||'')).filter(Boolean));
    vs.forEach(v=>{
      const plate=vehicleShown(v.placa),plateKey=vehiclePlateKey(v),root=vehicleLineageRoot(v,byId),hasLineage=!!String(v&&v.versionOfVehicleId||'')||referenced.has(String(v&&v.id||''));
      const linkedPolicy=S().get('polizas',v.polizaId)||{},linkedCurrent=policyBusinessRank(linkedPolicy)<=1;
      if(!hasLineage&&!plateKey&&!linkedCurrent){ambiguous.push(v);return;}
      const key=plateKey?('plate:'+plateKey):(hasLineage?('lineage:'+root):('current:'+String(v.id||v.polizaId||'')));
      if(!groups.has(key))groups.set(key,[]);groups.get(key).push(v);
    });
    const cards=Array.from(groups.entries()).map(([groupKey,records])=>{
      records.sort(vehiclePolicyCompare);
      const v=records[0],p=S().get('polizas',v.polizaId),historyRecords=records.filter(h=>String(h.id)!==String(v.id));
      const historyLabel='vigencia(s) anterior(es) de este vehículo';
      const history=historyRecords.length?`<details style="margin-top:12px"><summary style="cursor:pointer;font-size:12.5px;font-weight:700;color:var(--ink-2)">${historyRecords.length} ${historyLabel}</summary><div style="display:grid;gap:7px;margin-top:9px">${historyRecords.map(h=>{const hp=S().get('polizas',h.polizaId)||{};return `<div style="padding:8px 10px;border:1px solid var(--line);border-radius:10px;font-size:12px"><b>${U.esc(vehicleShown(h.marca))} ${U.esc(vehicleShown(h.linea))} · ${U.esc(vehicleShown(h.placa))}</b><div class="muted">${U.esc(vehicleShown(hp.numero))} · ${U.fmtDate(hp.vigenciaInicio)} → ${U.fmtDate(hp.vigenciaFin)} · ${U.esc(vehicleShown(hp.estado))}</div><div style="margin-top:6px;display:flex;gap:6px;flex-wrap:wrap"><button class="btn ghost sm" onclick="Orbit.modules.cliente360.verVehiculo('${h.id}')">Ver registro</button><button class="btn ghost sm" onclick="Orbit.modules.cliente360.verPoliza('${h.polizaId}')">Ver póliza</button></div></div>`;}).join('')}</div></details>`:'';
      return `<div class="card pad" data-vehicle-current-card="1" data-vehicle-current-id="${U.esc(String(v.id||''))}" data-vehicle-policy-id="${U.esc(String(v.polizaId||''))}" data-vehicle-plate-key="${U.esc(vehiclePlateKey(v))}" data-vehicle-history-count="${historyRecords.length}"><div style="display:flex;align-items:center;gap:12px;margin-bottom:12px"><span style="width:46px;height:46px;border-radius:11px;background:var(--red-soft);display:grid;place-items:center;font-size:22px">🚗</span><div><b style="font-family:var(--f-display);font-size:16px">${U.esc(vehicleShown(v.marca))} ${U.esc(vehicleShown(v.linea))}</b><div class="muted mono" style="font-size:12px">${U.esc(vehicleShown(v.placa))} · ${U.esc(vehicleShown(v.anio))}</div></div><span class="badge ${p && p.estado === 'Vigente' ? 'ok' : p && p.estado === 'Por renovar' ? 'warn' : 'neutral'}" style="margin-left:auto">${p ? U.esc(vehicleShown(p.estado)) : '—'}</span></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:9px;font-size:12.5px">${vrow('Uso',v.uso)}${vrow('Color',v.color)}${vrow('Chasis (VIN)',v.chasis)}${vrow('Motor',v.motor)}${vrow('Suma asegurada',U.money(v.sumaAsegurada,p?p.moneda:'GTQ'))}${vrow('Póliza',p?p.numero:'—')}</div><div style="margin-top:12px;display:flex;gap:8px;flex-wrap:wrap"><button class="btn ghost sm" onclick="Orbit.modules.cliente360.verVehiculo('${v.id}')">Ver vehículo</button><button class="btn ghost sm" onclick="Orbit.modules.cliente360.editarVehiculo&&Orbit.modules.cliente360.editarVehiculo('${v.id}')">Editar vehículo</button><button class="btn ghost sm" onclick="Orbit.modules.cliente360.verPoliza('${v.polizaId}')">Ver póliza</button><button class="btn ghost sm" onclick="Orbit.importa.open('polizas')">Importar documentos</button></div>${history}</div>`;
    });
    const unresolved=ambiguous.length?`<div class="card pad" data-vehicle-identity-incomplete="1" style="grid-column:1/-1;border-left:3px solid var(--warn)"><b>Pendientes de relacionar o revisar</b><div class="muted" style="margin:5px 0 10px">Estos registros conservan su historial, pero necesitan una relación o identidad suficiente antes de mostrarse como un mismo vehículo.</div><div style="display:grid;gap:7px">${ambiguous.sort(vehiclePolicyCompare).map(h=>{const hp=S().get('polizas',h.polizaId)||{};return `<div style="padding:8px 10px;border:1px solid var(--line);border-radius:10px"><b>${U.esc(vehicleShown(h.marca))} ${U.esc(vehicleShown(h.linea))}</b><div class="muted">${U.esc(vehicleShown(hp.numero))} · ${U.fmtDate(hp.vigenciaInicio)} → ${U.fmtDate(hp.vigenciaFin)} · ${U.esc(vehicleShown(hp.estado))}</div><div style="margin-top:6px;display:flex;gap:6px"><button class="btn ghost sm" onclick="Orbit.modules.cliente360.verVehiculo('${h.id}')">Ver registro</button><button class="btn ghost sm" onclick="Orbit.modules.cliente360.verPoliza('${h.polizaId}')">Ver póliza</button></div></div>`;}).join('')}</div></div>`:'';
    return `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:14px">${cards.join('')}${unresolved}</div>`;
  }
  function vrow(k,v){return `<div><div style="font-size:12px;font-weight:600;color:var(--ink-2);text-transform:uppercase;letter-spacing:.035em">${k}</div><div style="font-weight:500;margin-top:2px">${U.esc(vehicleShown(v))}</div></div>`; }

  /* ---- Documentos del cliente · Drive como repositorio documental ---- */
  function tabDocumentos(cid, r) {
    const cli = S().get('clientes', cid) || r.cli || {};
    const docs = Array.isArray(cli.documentos) ? cli.documentos : [];
    const uploadStatus = Orbit.secureResources && Orbit.secureResources.documentUploadStatus
      ? Orbit.secureResources.documentUploadStatus({ entidad: 'cliente', entidadId: cid, clienteId: cid })
      : { available: false, status: 'checking', backendPersistent: true };
    const canManageDocs = !!(Orbit.access && Orbit.access.can && (Orbit.access.can('cliente360','manage_documents') || Orbit.access.can('cliente360','edit')));
    const directUpload = canManageDocs && uploadStatus && uploadStatus.available === true && uploadStatus.uploadAvailable !== false;
    const needsBootstrap = canManageDocs && uploadStatus && uploadStatus.bootstrapRequired === true;
    const cards = docs.map((d, i) => '<div class="card pad" style="display:flex;gap:12px;align-items:center">'
      + '<div style="font-size:24px">📄</div><div style="flex:1;min-width:0"><b style="font-family:var(--f-display);font-size:13.5px">' + U.esc(d.nombre || ('Documento ' + (i + 1))) + '</b>'
      + '<div class="muted" style="font-size:11.5px;margin-top:3px">' + U.esc(d.categoria || 'Expediente') + ' · ' + U.esc(d.origen || 'Drive') + (d.creado ? ' · ' + U.esc(d.creado) : '') + '</div></div>'
      + '<button class="btn ghost sm" data-client-doc="' + i + '">Abrir</button></div>').join('');
    return '<div class="card pad" style="margin-bottom:12px"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap">'
      + '<div><b style="font-family:var(--f-display);font-size:16px">📎 Documentos del cliente</b><div class="muted" style="font-size:12px;margin-top:4px">Drive es el repositorio documental; Gravicentra controla el acceso según tu rol y alcance.</div></div>'
      + '<div style="display:flex;gap:8px;flex-wrap:wrap">'
      + (cli.driveLink ? '<a class="btn ghost sm" href="' + U.esc(cli.driveLink) + '" target="_blank" rel="noopener">📁 Abrir en Drive</a>' : '')
      + (canManageDocs ? '<button class="btn ghost sm" data-doc-intelligent>🧠 Importar y extraer datos</button>' : '')
      + (needsBootstrap ? '<button class="btn ghost sm" data-doc-bootstrap>⚙ Configurar Drive</button>' : '')
      + (canManageDocs ? '<button class="btn primary sm" data-doc-upload>' + (directUpload ? '⬆ Cargar documento' : '📎 Cargar documento') + '</button>' : '')
      + '</div></div>'
      + (needsBootstrap ? '<div class="cfg-note" style="margin-top:12px">Drive requiere una configuración administrativa única. Después, los usuarios autorizados trabajarán con el expediente sin conectar cuentas Google.</div>' : '')
      + '</div><div style="display:grid;gap:10px">' + (cards || '<div class="card pad" style="text-align:center;color:var(--ink-2);padding:28px">Todavía no hay documentos con vínculo Drive confirmado en esta ficha.</div>') + '</div>';
  }

  function wireDocumentos(cid) {
    const body = document.getElementById('c360-body');
    if (!body) return;
    const cli = S().get('clientes', cid) || {};
    body.querySelectorAll('[data-client-doc]').forEach(btn => btn.addEventListener('click', () => {
      const d = (Array.isArray(cli.documentos) ? cli.documentos : [])[+btn.dataset.clientDoc];
      if (!d) return;
      if (Orbit.documentViewer && typeof Orbit.documentViewer.open === 'function') Orbit.documentViewer.open(d, { context: { entidad: 'cliente', entidadId: cid, clienteId: cid } });
      else {
        const url = String(d.driveUrl || d.externalUrl || d.url || '').trim();
        if (/^https:\/\/[^\s]+$/i.test(url)) window.open(url, '_blank', 'noopener,noreferrer');
      }
    }));
    async function ensureRepository() {
      const provider = Orbit.productDriveDocumentProviderP0;
      if (!provider || typeof provider.probe !== 'function') { c360toast('El repositorio documental no está disponible.'); return false; }
      const st = await provider.probe(true);
      if (!st || st.available !== true) { c360toast((st && st.message) || 'El repositorio documental no está disponible.'); return false; }
      return true;
    }
    // R84: document provider status resolves asynchronously. If the first render
    // happened while status was still "checking", refresh this tab once when
    // the backend confirms that the tenant needs its one-time Drive bootstrap.
    const driveProvider = Orbit.productDriveDocumentProviderP0;
    const activeDriveRole = (() => {
      try { return String(Orbit.session && Orbit.session.rol ? Orbit.session.rol() : '').trim(); }
      catch (_) { return ''; }
    })();
    const mayBootstrapDrive = /^(Dirección|Direccion|SuperAdmin|AdminTenant|Admin)$/i.test(activeDriveRole);
    if (driveProvider && typeof driveProvider.probe === 'function' && mayBootstrapDrive && !body.querySelector('[data-doc-bootstrap]')) {
      driveProvider.probe(true).then(st => {
        if (!st || st.bootstrapRequired !== true) return;
        if (document.getElementById('c360-body') !== body || tab !== 'documentos') return;
        Orbit.modules.cliente360.reabrir(cid, 'documentos');
      }).catch(() => {});
    }

    const bootstrap = body.querySelector('[data-doc-bootstrap]');
    if (bootstrap) bootstrap.addEventListener('click', async () => {
      const provider = Orbit.productDriveDocumentProviderP0;
      if (!provider || typeof provider.bootstrap !== 'function') { c360toast('La configuración administrativa de Drive no está disponible.'); return; }
      bootstrap.disabled = true;
      const out = await provider.bootstrap();
      bootstrap.disabled = false;
      c360toast((out && out.ok === true) ? 'Drive quedó conectado de forma persistente para el tenant.' : ((out && out.message) || 'No fue posible configurar Drive.'));
      Orbit.modules.cliente360.reabrir(cid, 'documentos');
    });
    const upload = body.querySelector('[data-doc-upload]');
    if (upload) upload.addEventListener('click', async () => {
      if (!(await ensureRepository())) return;
      Orbit.importa.open('documentos', { multi: true, modo: 'documental', scope: { cid, nombre: cli.nombre || 'Cliente' }, onDone: () => Orbit.modules.cliente360.reabrir(cid, 'documentos') });
    });
    const intelligent = body.querySelector('[data-doc-intelligent]');
    if (intelligent) intelligent.addEventListener('click', async () => {
      if (!(await ensureRepository())) return;
      Orbit.importa.open('documentos', { multi: true, modo: 'inteligente', scope: { cid, nombre: cli.nombre || 'Cliente' }, onDone: () => Orbit.modules.cliente360.reabrir(cid, 'documentos') });
    });
  }

  /* ---- Recibos y cobros (filtro por póliza + confirmar cobro) ---- */
  let recPolFiltro = {};  // por cliente: polizaId seleccionada
  function tabRecibos(cid, r) {
    const cobAll = r.cob.slice().sort((a, b) => String(a.vence||'').localeCompare(String(b.vence||'')));
    const polis = S().where('polizas', p => p.clienteId === cid);
    const sel = recPolFiltro[cid] || 'todas';
    const cob = sel === 'todas' ? cobAll : cobAll.filter(c => c.polizaId === sel);
    const pend = cob.filter(c => c.estado === 'Pendiente' || c.estado === 'Vencido');
    const cobradoPorMoneda = sourceCurrencyTotals(cob.filter(c => c.estado === 'Pagado'), c => c.monto,
      c => c.moneda || ((S().get('polizas', c.polizaId) || {}).moneda));
