    const tot = com.reduce((s, c) => s + c.monto, 0);
    const liq = com.filter(c => c.estado === 'Liquidada').reduce((s, c) => s + c.monto, 0);
    const vendedor = Math.round(tot * 0.6), empresa = tot - vendedor; // split demo 60/40
