        <div style="margin-top:12px;display:grid;gap:9px">
          <select id="na-tipo" class="o-sel" style="width:100%">
            <option value="📞|llamada">📞 Llamada</option>
            <option value="💬|whatsapp">💬 WhatsApp</option>
            <option value="✉|email">✉ Correo</option>
            <option value="🤝|reunion">🤝 Reunión</option>
            <option value="📝|nota">📝 Nota</option>
          </select>
          <input id="na-tit" class="o-sel" style="width:100%" placeholder="Título (p. ej. Llamada de seguimiento)">
          <textarea id="na-det" class="o-sel" style="width:100%;min-height:74px;resize:vertical;padding:9px 11px" placeholder="Detalle…"></textarea>
          <button class="btn primary" id="na-save">Agregar al historial</button>
          <div id="na-status" class="muted" role="status" aria-live="polite" style="font-size:12px"></div>
          <div class="muted" style="font-size:11.5px">Queda registrado en el expediente y disponible para Insights y Marketing.</div>
        </div>
      </div>
    </div>`;
  }
  function historyScope() {
    const m = Orbit.auth && Orbit.auth.productUser || {};
    return [String(m.tenantId || ''), String(m.uid || ''), ROLE_NORM()].join('|');
  }
  function historyDraft(cid) {
    const scope = historyScope(), key = scope + '|' + String(cid);
    if (!historyDrafts.has(key)) historyDrafts.set(key, {
      cid, scope, fields: { type: '📞|llamada', title: '', detail: '' },
      attempt: null, inFlight: false, message: ''
    });
    return historyDrafts.get(key);
  }
  function rememberHistoryDraft() {
    const view = historyView;
    if (!view || view.state.scope !== historyScope() || !view.title.isConnected || !view.detail.isConnected) return;
    view.state.fields = { type: view.type.value, title: view.title.value, detail: view.detail.value };
  }
  function currentHistoryView(state) {
    return historyView && historyView.state === state && state.scope === historyScope() &&
      shownCid === state.cid && tab === 'historial' && host && host.isConnected &&
      document.getElementById('na-save') === historyView.save;
  }
  function repaintHistoryOutcome(state) {
    if (!currentHistoryView(state)) return;
    // The state already contains any newer text typed while the server replied.
    // Do not capture the old form over a successfully cleared submitted draft.
    historyView = null;
    renderTab(state.cid, summaryForDetail(state.cid));
  }
  function wireHistorial(cid) {
    const save = document.getElementById('na-save'); if (!save) return;
    const state = historyDraft(cid), view = {
      state, save, type: document.getElementById('na-tipo'), title: document.getElementById('na-tit'),
      detail: document.getElementById('na-det'), status: document.getElementById('na-status')
    };
    historyView = view;
    view.type.value = state.fields.type; view.title.value = state.fields.title; view.detail.value = state.fields.detail;
    save.disabled = state.inFlight;
    save.textContent = state.inFlight ? 'Confirmando…' : state.attempt ? 'Reintentar confirmación' : 'Agregar al historial';
    view.status.textContent = state.message;
    for (const field of [view.type, view.title, view.detail]) {
      for (const event of ['input', 'change']) field.addEventListener(event, () => {
        if (currentHistoryView(state)) rememberHistoryDraft();
      });
    }
    save.addEventListener('click', async () => {
      if (state.inFlight || !currentHistoryView(state)) return;
      rememberHistoryDraft();
      const client = S().get('clientes', cid);
      if (!client || !clientInCurrentCountry(client) || typeof S().batchDurable !== 'function') {
        state.message = 'No fue posible verificar el cliente y el guardado. El texto se conserva.';
        view.status.textContent = state.message; return;
      }
      if (!state.attempt) {
        const draft = { ...state.fields }, [icon, tipo] = (draft.type || '📝|nota').split('|');
        const nonce = window.crypto && typeof window.crypto.randomUUID === 'function'
          ? window.crypto.randomUUID() : Date.now().toString(36) + '_' + Math.random().toString(36).slice(2);
        const requestId = 'cli_history_' + nonce;
        const activity = { id: 'act_' + requestId, clienteId: cid, pais: client.pais,
          tenantId: client.tenantId || '', asesorId: client.asesorId, tipo, icon,
          fecha: Orbit.ui.today(), titulo: draft.title.trim() || 'Nota', detalle: draft.detail.trim() || '—',
          operacionId: requestId };
        markPreviewClientActivity(client, activity, window.location.hostname);
        state.attempt = { requestId, activity, draft, uncertain: false };
      }
      const attempt = state.attempt;
      state.inFlight = true; state.message = 'Confirmando la interacción…';
      save.disabled = true; save.textContent = 'Confirmando…'; view.status.textContent = state.message;
      try {
        const result = await S().batchDurable([{ action: 'insert', collection: 'actividades',
          id: attempt.activity.id, payload: attempt.activity }], { requestId: attempt.requestId, activityRetry: true });
        const proof = result && Array.isArray(result.readback) && result.readback.find(row =>
          row.collection === 'actividades' && row.id === attempt.activity.id && row.action === 'insert' && row.exists === true);
        if (!result || result.ok !== true || result.serverOwned !== true || result.canonicalReadback !== true || !proof)
          throw new Error('PRODUCT_SERVER_CANONICAL_READBACK_REQUIRED');
        rememberHistoryDraft();
        if (JSON.stringify(state.fields) === JSON.stringify(attempt.draft))
          state.fields = { type: state.fields.type, title: '', detail: '' };
        state.attempt = null;
        state.message = 'Interacción guardada y confirmada.';
      } catch (error) {
        rememberHistoryDraft();
        const code = String(error && (error.code || error.message) || '').replace(/^functions\//, '');
        const definite = ['permission-denied', 'unauthenticated', 'invalid-argument', 'failed-precondition',
          'not-found', 'PRODUCT_WRITE_ACCESS_DENIED', 'PRODUCT_WRITE_RECORD_SCOPE_DENIED'].includes(code);
        if (definite && !attempt.uncertain) state.attempt = null;
        else attempt.uncertain = true;
        state.message = state.attempt
          ? 'No se pudo confirmar la interacción. Tu texto se conserva; Reintentar confirmación verifica la misma operación sin crear otra.'
          : 'El servidor no autorizó el guardado. El texto se conserva para corregirlo o volver a intentarlo.';
      } finally {
        state.inFlight = false;
        // A late response only updates its own draft; never reopens an old client.
        repaintHistoryOutcome(state);
      }
    });
  }

  /* I6.6: one server-owned, country-scoped advisor roster for Cliente 360.
     Never use the protected/historical asesores store as an assignment selector.
     The source remains Equipos via orbit360AssignableAdvisorRoster. */
  function bindAssignableClientAdvisors(back, selectId, countryEl, saveId, previous) {
    const field=back.querySelector('#'+selectId), save=back.querySelector('#'+saveId);
    const priorId=String(previous?.id||'').trim(),priorCountry=String(previous?.country||'').toUpperCase();
    let sequence=0,ready=false,rows=[],historical=false;
    const allowed=()=>ready&&!!field.value&&
      (rows.some(a=>a.id===field.value) ||
       (historical&&field.value===priorId&&countryEl.value===priorCountry));
    const load=async preferred=>{
      const id=++sequence,country=String(countryEl.value||'').toUpperCase();
      ready=false;rows=[];historical=false;field.disabled=true;save.disabled=true;
      field.dataset.rosterState='loading';
      field.innerHTML='<option value="">Consultando el equipo autorizado…</option>';
      try{
        const api=Orbit.assignableAdvisorRoster;
        if(!api||typeof api.list!=='function'||!['GT','CO'].includes(country))
          throw Error('CANONICAL_ASSIGNABLE_ADVISOR_REQUIRED');
        const response=await api.list(country,{force:true});
        if(!back.isConnected||sequence!==id)return;
        const seen=new Set();
        rows=response.filter(a=>{
          if(!a?.id||!a.nombre||a.assignable!==true||a.roleEligible!==true||a.activo===false||
             ![].concat(a.paises||[]).includes(country)||seen.has(a.id))return false;
          seen.add(a.id);return true;
        });
        field.innerHTML='<option value="">— Seleccionar asesor habilitado —</option>'+
          rows.map(a=>'<option value="'+U.esc(a.id)+'">'+U.esc(a.nombre)+'</option>').join('');
        const wanted=String(preferred||'').trim();
        if(wanted&&rows.some(a=>a.id===wanted))field.value=wanted;
        else if(wanted===priorId&&priorId&&priorCountry===country){
          // Preserve only the same historical assignment, never offer it as a new choice.
          const label=(q.asesor(priorId,country)||{}).nombre||'Asesor histórico';
          field.insertAdjacentHTML('beforeend','<option value="'+U.esc(priorId)+'" data-historical="1">'+
            U.esc(label)+' · asignación histórica</option>');
          field.value=priorId;historical=true;
        }
        ready=true;field.disabled=false;field.dataset.rosterState='ready';
        field.dataset.rosterCountry=country;field.dataset.rosterCount=String(rows.length);
        save.disabled=!allowed();
      }catch(error){
        if(!back.isConnected||sequence!==id)return;
        field.dataset.rosterState='blocked';
        field.innerHTML='<option value="">No se pudo confirmar el equipo; no se guardó ningún cambio</option>';
        field.disabled=true;save.disabled=true;
        try{console.warn('[Gravicentra][Cliente360] CANONICAL_ADVISOR_ROSTER_UNAVAILABLE',{country});}catch(_){}
      }
    };
    field.addEventListener('change',()=>{save.disabled=!allowed();});
    countryEl.addEventListener('change',()=>{void load(countryEl.value===priorCountry?priorId:'');});
    void load(priorId);
    return Object.freeze({allowed,refresh:load});
  }

