    if (!/^ays-orbit-360-lab--gi-i66-rc-[a-z0-9-]+\.web\.app$/i.test(hostname)) return;
    if (client.__syntheticQa !== true || !/^b4003qa_[A-Za-z0-9._:-]+$/.test(client.id)) return;
    const history = activity.id.startsWith('act_cli_history_') && activity.id === 'act_' + activity.operacionId;
    if (activity.clienteId === client.id && (activity.id.startsWith('act_cli_edit_' + client.id + '_') || history)) {
      activity.__syntheticQa = true;
      if (history) activity.id = 'b4003qa_' + activity.id;
    }
  }
